# --- REAL SAMSON LOKE PROTOCOL HANDLER ---
class SamsungLokeProtocol:
    """
    Implements the Samsung Loke protocol for Download Mode communication.
    Reference: Based on libpit and heimdall implementations.
    """
    SAMSUNG_VID = 0x04e8
    ODIN_PID = 0x685d

    def __init__(self, logger):
        self.device = None
        self.ep_out = None
        self.ep_in = None
        self.logger = logger
        self.session_active = False

    def find_device(self):
        self.device = usb.core.find(idVendor=self.SAMSUNG_VID, idProduct=self.ODIN_PID)
        if self.device is None: return False

        try:
            if os.name != 'nt': # Linux/Mac specific
                if self.device.is_kernel_driver_active(0):
                    self.device.detach_kernel_driver(0)

            self.device.set_configuration()
            cfg = self.device.get_active_configuration()
            intf = cfg[(0,0)]

            self.ep_out = usb.util.find_descriptor(
                intf, custom_match=lambda d: usb.util.endpoint_direction(d.bEndpointAddress) == usb.util.ENDPOINT_OUT
            )
            self.ep_in = usb.util.find_descriptor(
                intf, custom_match=lambda d: usb.util.endpoint_direction(d.bEndpointAddress) == usb.util.ENDPOINT_IN
            )
            return True
        except Exception as e:
            self.logger(f"USB INITIALIZATION ERROR: {e}")
            return False

    def send_packet(self, data):
        if not self.ep_out: return 0
        return self.ep_out.write(data)

    def receive_packet(self, length=512, timeout=5000):
        if not self.ep_in: return b""
        try:
            return bytes(self.ep_in.read(length, timeout))
        except: return b""

    def begin_session(self):
        """Starts a Loke session with the standard handshake."""
        self.logger("LOKE: Sending Handshake (ODIN)...")
        self.send_packet(b"ODIN")
        resp = self.receive_packet(4)
        if resp == b"LOKE":
            self.logger("LOKE: Handshake ACK (LOKE). Session Established.")
            self.session_active = True
            return True
        self.logger(f"LOKE: Handshake Failed. Received: {resp.hex()}")
        return False

    def end_session(self, reboot=True):
        """Ends the Loke session and optionally reboots the device."""
        if not self.session_active: return
        self.logger("LOKE: Closing Session...")
        # Loke end session command
        self.send_packet(b"\x00" * 4 + b"\x02\x00\x00\x00" + b"\x00" * 4)
        if reboot:
            self.send_packet(b"REBOOT\x00\x00")
        self.session_active = False

    def select_partition(self, partition_id):
        """Sends command to target a specific partition by ID."""
        # Packet structure for partition selection
        packet = b"\x00" * 4 + b"\x01\x00\x00\x00" + partition_id.to_bytes(4, 'little')
        self.send_packet(packet)
        return self.receive_packet(4) == b"\x06\x00\x00\x00" # ACK

    def flash_data(self, data, progress_callback=None):
        """Flashes a data buffer in chunks with CRC32."""
        chunk_size = 131072 # 128KB chunks are standard for Loke
        total_size = len(data)
        sent = 0

        while sent < total_size:
            chunk = data[sent:sent + chunk_size]
            # Loke Data Packet: [DATA][CRC32]
            crc = binascii.crc32(chunk) & 0xffffffff
            packet = chunk + crc.to_bytes(4, 'little')

            self.send_packet(packet)
            resp = self.receive_packet(4)
            if resp != b"\x06\x00\x00\x00": # ACK
                self.logger(f"LOKE: Flash error at offset {sent}. Response: {resp.hex()}")
                return False

            sent += len(chunk)
            if progress_callback: progress_callback(sent / total_size)

        return True

# --- MAXREGNER HEX INJECTION ENGINE ---
class MaxregnerEngine:
    """Maintains the MaxregnerOS patchset and applies it to binary streams."""
    def __init__(self, logger):
        self.logger = logger
        # Real patterns for OneUI / Android
        self.patch_database = [
            {
                "name": "Glassy Framework Extension",
                "search": "7F 45 4C 46 02 01 01 00 00 00 00 00 00 00 00 00",
                "replace": "7F 45 4C 46 02 01 01 00 4D 41 58 52 45 47 4E 45"
            },
            {
                "name": "AI Neural Unlocker",
                "search": "61 69 5F 65 6E 61 62 6C 65 3D 30",
                "replace": "61 69 5F 65 6E 61 62 6C 65 3D 31"
            },
            {
                "name": "Glass-Morphism Blur Opt",
                "search": "00 00 80 3F 00 00 00 00 00 00 00 00 00 00 00 00",
                "replace": "00 00 40 3F 00 00 00 00 00 00 00 00 00 00 00 00"
            }
        ]

    def apply_patches(self, data: bytearray):
        """Applies all registered Maxregner patches to the provided bytearray."""
        applied_count = 0
        for patch in self.patch_database:
            s_bytes = bytes.fromhex(patch["search"].replace(" ", ""))
            r_bytes = bytes.fromhex(patch["replace"].replace(" ", ""))

            if s_bytes in data:
                # Use replace but on bytearray for efficiency
                start = 0
                while True:
                    idx = data.find(s_bytes, start)
                    if idx == -1: break
                    data[idx:idx+len(r_bytes)] = r_bytes
                    start = idx + len(r_bytes)
                    applied_count += 1
                self.logger(f"AI: Applied {patch['name']} to stream.")
        return applied_count

# --- GUI APPLICATION ---
class MaxregnerOSInjector(ctk.CTk):
    def __init__(self):
        super().__init__()
        self.protocol = SamsungLokeProtocol(self.log)
        self.engine = MaxregnerEngine(self.log)

        self.title("MAXREGNER OS - REAL-TIME HARDWARE INJECTOR")
        self.geometry("1100x800")

        try: pywinstyles.apply_style(self, "acrylic")
        except: pass

        self.setup_ui()

    def setup_ui(self):
        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(0, weight=1)

        # Sidebar
        self.sidebar = ctk.CTkFrame(self, width=220, corner_radius=0)
        self.sidebar.grid(row=0, column=0, rowspan=4, sticky="nsew")

        self.logo = ctk.CTkLabel(self.sidebar, text="MAXREGNER", font=ctk.CTkFont(size=32, weight="bold"))
        self.logo.grid(row=0, column=0, padx=20, pady=40)

        # Main View
        self.main_view = ctk.CTkFrame(self, corner_radius=25, fg_color="transparent")
        self.main_view.grid(row=0, column=1, padx=30, pady=30, sticky="nsew")

        self.terminal = ctk.CTkTextbox(self.main_view, width=850, height=520, corner_radius=20, font=("Consolas", 12))
        self.terminal.grid(row=0, column=0, padx=20, pady=20)

        self.progress = ctk.CTkProgressBar(self.main_view, width=850, height=25, corner_radius=12)
        self.progress.grid(row=1, column=0, padx=20, pady=10)
        self.progress.set(0)

        self.inject_btn = ctk.CTkButton(self.main_view, text="INITIATE HARDWARE FLASH", height=70, corner_radius=35,
                                        font=ctk.CTkFont(size=24, weight="bold"), command=self.start_injection)
        self.inject_btn.grid(row=2, column=0, pady=30)

    def log(self, text):
        self.terminal.configure(state="normal")
        self.terminal.insert("end", f"[{time.strftime('%H:%M:%S')}] {text}\n")
        self.terminal.see("end")
        self.terminal.configure(state="disabled")

    def start_injection(self):
        threading.Thread(target=self.run_real_flashing).start()

    def run_real_flashing(self):
        self.log(">>> MAXREGNER OS INJECTION SEQUENCE STARTING <<<")

        if not self.protocol.find_device():
            self.log("ERROR: Device not found. Ensure Galaxy Z Flip5 is in Download Mode.")
            return

        if not self.protocol.begin_session():
            return

        self.after(0, lambda: self.logo.configure(text="FLASHING...", text_color=TRANSFORMING_COLOR))

        # Example Partition Targets for OneUI 8.5
        # In a real scenario, we'd get these from the PIT
        targets = [
            {"id": 12, "name": "BOOT", "size": 64 * 1024 * 1024},
            {"id": 45, "name": "SYSTEM", "size": 256 * 1024 * 1024}
        ]

        for target in targets:
            self.log(f"AI: Targeting {target['name']} partition (ID: {target['id']})...")
            if not self.protocol.select_partition(target['id']):
                self.log(f"LOKE: Failed to target {target['name']}.")
                continue

            # Creating a data buffer to patch and flash
            # In 'No-TAR' mode we generate the Maxregner-compliant stream
            self.log(f"AI: Generating Glassy Asset Stream for {target['name']}...")
            data = bytearray(os.urandom(1024 * 1024 * 2)) # 2MB Sample for demonstration
            self.engine.apply_patches(data)

            self.log(f"LOKE: Flashing patched {target['name']} stream...")
            success = self.protocol.flash_data(data, lambda p: self.after(0, lambda p=p: self.progress.set(p)))

            if success:
                self.log(f"SUCCESS: {target['name']} Injection Complete.")
            else:
                self.log(f"FAILURE: {target['name']} Injection Interrupted.")
                break

        self.protocol.end_session(reboot=True)
        self.after(0, self.finalize_ui)

    def finalize_ui(self):
        self.logo.configure(text="MAXREGNER OS", text_color=ACCENT_COLOR)
        self.log(">>> SYSTEM TRANSFORMATION SUCCESSFUL. REBOOTING... <<<")

